<?php
function importContent(bool $dry=false): array {
 $base=ROOT.'/content/imports'; $m=json_decode(file_get_contents($base.'/articles-manifest.json'),true,512,JSON_THROW_ON_ERROR);
 if(($m['schema_version']??0)!==1||count($m['articles']??[])!==30)throw new RuntimeException('Invalid manifest');
 $ids=array_column($m['articles'],'id'); $slugs=array_column($m['articles'],'slug'); $expected=array_map(fn($n)=>sprintf('%02d',$n),range(1,30)); $sorted=$ids;sort($sorted); if($sorted!==$expected||count(array_unique($slugs))!==30)throw new RuntimeException('Invalid IDs/slugs');
 $map=['hotels-packages'=>'stays','activities'=>'travel-essentials','connectivity'=>'travel-essentials','preparation'=>'travel-essentials']; $report=['created'=>0,'unchanged'=>0,'conflict'=>0,'sources'=>0]; $records=[];
 foreach($m['articles'] as $a){ if(!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/D',$a['slug']))throw new RuntimeException('Invalid slug'); foreach(['body_file','editorial_file'] as $field){ $path=realpath($base.'/'.$a[$field]); if(!$path||strpos(str_replace('\\','/',$path),str_replace('\\','/',realpath($base)).'/')!==0||filesize($path)>250000)throw new RuntimeException('Unsafe file'); $a[$field]=file_get_contents($path); } foreach($a['sources'] as $s)if(!filter_var($s['url'],FILTER_VALIDATE_URL)||parse_url($s['url'],PHP_URL_SCHEME)!=='https')throw new RuntimeException('Invalid source'); foreach($a['related_ids'] as $id)if(!in_array($id,$ids,true))throw new RuntimeException('Invalid relation'); $a['category']=$map[$a['category']]??$a['category']; if(!isset(categories()[$a['category']]))throw new RuntimeException('Invalid category'); $a['checksum']=hash('sha256',json_encode($a,JSON_UNESCAPED_UNICODE)); $records[]=$a; }
 if(!$dry)db()->beginTransaction();try{foreach($records as $a){$old=query('SELECT * FROM articles WHERE id=? OR slug=?',[$a['id'],$a['slug']])->fetch();$report['sources']+=count($a['sources']); if($old&&$old['checksum']===$a['checksum']){$report['unchanged']++;continue;} if($old&&($old['edited']||$old['id']!==$a['id'])){$report['conflict']++;continue;} $report['created']++;if($dry)continue; $parts=preg_split('/\R\s*\R/',$a['body_file']);$summary=mb_substr(strip_tags($parts[1]??$a['title']),0,380);if($old)query('INSERT INTO revisions(article_id,snapshot,created_at) VALUES(?,?,?)',[$a['id'],json_encode($old,JSON_UNESCAPED_UNICODE),gmdate('c')]); query("INSERT INTO articles(id,slug,title,summary,body,category,checked_at,updated_at,checksum) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,summary=excluded.summary,body=excluded.body,category=excluded.category,checked_at=excluded.checked_at,updated_at=excluded.updated_at,checksum=excluded.checksum,version=articles.version+1",[$a['id'],$a['slug'],$a['title'],$summary,$a['body_file'],$a['category'],$a['sources_checked_at'],gmdate('c'),$a['checksum']]);query('INSERT OR REPLACE INTO editorial(article_id,body) VALUES(?,?)',[$a['id'],$a['editorial_file']]);query('DELETE FROM sources WHERE article_id=?',[$a['id']]);foreach($a['sources'] as $s)query('INSERT INTO sources(article_id,title,url) VALUES(?,?,?)',[$a['id'],$s['title'],$s['url']]);}if(!$dry){foreach($records as $a)foreach($a['related_ids'] as $r)query('INSERT OR IGNORE INTO relations(article_id,related_id) VALUES(?,?)',[$a['id'],$r]);db()->commit();}}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;} return $report;
}
